class EqualityExpressionEnum(Enum):
    """
    Indicates the logical comparator to use.

    :cvar GREATER_THAN: Indicates the condition is true if the value
        under test is greater than the reference value.
    :cvar GREATER_THAN_EQUAL_TO: Indicates the condition is true if the
        value under test is greater than or equal to the reference
        value.
    :cvar LESS_THAN: Indicates the condition is true if the value under
        test is less than the reference value.
    :cvar LESS_THAN_EQUAL_TO: Indicates the condition is true if the
        value under test is less than or equal to the reference value.
    :cvar EQUAL_TO: Indicates the condition is true if the values are
        equal.
    :cvar NOT_EQUAL_TO: Indicates the condition is true if the values
        are not equal.
    """

    GREATER_THAN = "GREATER_THAN"
    GREATER_THAN_EQUAL_TO = "GREATER_THAN_EQUAL_TO"
    LESS_THAN = "LESS_THAN"
    LESS_THAN_EQUAL_TO = "LESS_THAN_EQUAL_TO"
    EQUAL_TO = "EQUAL_TO"
    NOT_EQUAL_TO = "NOT_EQUAL_TO"


