class IntegrationMethodEnum(Enum):
    """
    Contains the integration methods that are supported.

    :cvar RUNGE_KUTTA_4: A Runge-Kutta 4th-order integrator. Also known
        as RK4. No error control for the integration step size is
        included for this integrator. It is always fixed-step.
    :cvar RUNGE_KUTTA_FEHLBERG_78: A Runge-Kutta-Fehlberg adaptive-step,
        7th-order integrator with 8th-order error control for
        integration step size. Also known as RKF78
    :cvar RUNGE_KUTTA_VERNER_89: A Runge-Kutta-Verner adaptive-step,
        8th-order integrator with 9th-order error control for
        integration step size. Also known as RKV89
    :cvar BULIRSCH_STOER: A Bulirsch-Stoer adaptive-step integrator.
    :cvar GAUSS_JACKSON: A Gauss-Jackson integrator with no error
        control for integration step size.
    :cvar PRINCE_DORMAND_54: A Prince-Dormand adaptive-step, 5th-order
        integrator with 4th-order error control for integration step
        size.
    :cvar PRINCE_DORMAND_853: A Prince-Dormand adaptive-step, 8th-order
        integrator with 5th-order error control for integration step
        size that also includes a 3rd-order correction.
    :cvar PRINCE_DORMAND_87: A Prince-Dormand adaptive-step, 8th-order
        integrator with 7th-order error control for integration step
        size.
    """

    RUNGE_KUTTA_4 = "RUNGE_KUTTA_4"
    RUNGE_KUTTA_FEHLBERG_78 = "RUNGE_KUTTA_FEHLBERG_78"
    RUNGE_KUTTA_VERNER_89 = "RUNGE_KUTTA_VERNER_89"
    BULIRSCH_STOER = "BULIRSCH_STOER"
    GAUSS_JACKSON = "GAUSS_JACKSON"
    PRINCE_DORMAND_54 = "PRINCE_DORMAND_54"
    PRINCE_DORMAND_853 = "PRINCE_DORMAND_853"
    PRINCE_DORMAND_87 = "PRINCE_DORMAND_87"


