    CAS = "CAS"
    RTB = "RTB"
    TANKER = "TANKER"
    TERMINATE = "TERMINATE"
    COUPLING = "COUPLING"
    ASSOCIATION = "ASSOCIATION"
    CONTROLLING_AGENCY = "CONTROLLING_AGENCY"


