    PREPARE_FOR_UPLOAD = "PREPARE_FOR_UPLOAD"
    UPLOAD = "UPLOAD"
    PREPARE_FOR_ACTIVATION = "PREPARE_FOR_ACTIVATION"
    ACTIVATE = "ACTIVATE"
    GO_TO_PART = "GO_TO_PART"
    DEACTIVATE = "DEACTIVATE"
    NO_CHANGE = "NO_CHANGE"


