@dataclass(kw_only=True)
class PlatformModeType:
    """
    Platform specific mode as reported by the system.

    This allows for the platform to report platform specific mode
    information.

    :ivar mode: Numeric mode of the platform reported by the system.
    :ivar description: Addtional platform mode details in a human
        readable text description.
    """

    mode: int = field(
        metadata={
            "name": "Mode",
            "type": "Element",
            "namespace": "https://www.vdl.afrl.af.mil/programs/oam",
        }
    )
    description: None | str = field(
        default=None,
        metadata={
            "name": "Description",
            "type": "Element",
            "namespace": "https://www.vdl.afrl.af.mil/programs/oam",
            "min_length": 1,
            "max_length": 32,
            "pattern": r"[ -~]{1,32}",
        },
    )


