    BIDIRECTIONAL_SECTOR = "BIDIRECTIONAL_SECTOR"
    MONOPULSE = "MONOPULSE"
    PASSIVE = "PASSIVE"
    OTHER = "OTHER"
    UNDETERMINED = "UNDETERMINED"


